import pandas as pd
schema_query = """
SELECT column_name 
FROM "information_schema"."columns" 
WHERE table_name = 'enterprise_data' 
AND LOWER(column_name) ILIKE '%allowance%'
"""
schema_result = execute_sql_query(schema_query)
has_allowance_columns = len(schema_result) > 0
if has_allowance_columns:
    allow_columns = [col for col in schema_result['column_name'] if 'etihad' in col.lower() or 'secondment' in col.lower()]
    if allow_columns:
        query = f"""
        SELECT 
            "[Employee Master[Employee Name]]",
            {', '.join([f'"{col}"' for col in allow_columns])}
        FROM enterprise_data
        """
        df = execute_sql_query(query)
        if len(df) > 0:
            results = []
            for idx, row in df.iterrows():
                emp_name = row['[Employee Master[Employee Name]]']
                etihad_val = row[[col for col in df.columns if 'Etihad' in col or 'etihad' in col.lower()]].iloc[0] if any('Etihad' in col or 'etihad' in col.lower() for col in df.columns) else None
                secondment_val = row[[col for col in df.columns if 'Secondment' in col or 'secondment' in col.lower()]].iloc[0] if any('Secondment' in col or 'secondment' in col.lower() for col in df.columns) else None
                if etihad_val is not None and secondment_val is not None:
                    diff = etihad_val - secondment_val
                    if diff > 0:
                        comparison = f'Etihad is higher by {diff}'
                    elif diff < 0:
                        comparison = f'Secondment is higher by {abs(diff)}'
                    else:
                        comparison = 'Both are equal'
                    results.append(f'{emp_name}: Etihad = {etihad_val}, Secondment = {secondment_val} ({comparison})')
                else:
                    results.append(f'{emp_name}: Allowance data incomplete')
            result = {'type': 'string', 'value': '\n'.join(results)}
        else:
            result = {'type': 'string', 'value': 'No employee records found with allowance data.'}
    else:
        result = {'type': 'string', 'value': 'Allowance columns found but not in expected format. Cannot determine Etihad and Secondment allowances.'}
else:
    result = {'type': 'string', 'value': 'No allowance columns found in the dataset. The available columns are only Employee Name and Email Address.'}
result = result
